import pytest


def grade(score):
    if score >= 90:
        return "A"
    if score >= 80:
        return "B"
    return "F"


@pytest.mark.parametrize(
    "score,expected",
    [(95, "A"), (90, "A"), (89, "B"), (80, "B"), (79, "F"), (0, "F")],
)
def test_grade(score, expected):
    assert grade(score) == expected

